import Foundation

enum PrecomputedTipTapIconData {
    private static let generatedDirectoryName = "GeneratedTipTapIconData"

    private static let values: [String: String] = [
        "1wavy": "",
        "2wavy": "",
        "3wavy": "",
        "4wavy": "",
        "5wavy": "",
        "boltprogress": "",
        "checkwavy": "",
        "chevdown": "",
        "chevright": "",
        "chevup": "",
        "codewindow": "",
        "linedpages": "",
        "linesbmark": "",
        "listcircle": "",
        "minuswavy": "",
        "numcal": "",
        "pagefold": "",
        "quote": "",
        "sparkle": "",
    ]

    static func base64(for icon: String) -> String? {
        if let bundled = values[icon] {
            return bundled
        }

        return persistentBase64(for: icon)
    }

    static func persist(base64: String, for icon: String) {
        guard let directory = persistentDirectoryURL() else { return }
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        try? base64.write(
            to: directory.appendingPathComponent("\(icon).b64"),
            atomically: true,
            encoding: .utf8
        )
    }

    private static func persistentBase64(for icon: String) -> String? {
        guard let directory = persistentDirectoryURL() else { return nil }
        let url = directory.appendingPathComponent("\(icon).b64")
        return try? String(contentsOf: url, encoding: .utf8)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func persistentDirectoryURL() -> URL? {
        FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first?
            .appendingPathComponent(generatedDirectoryName, isDirectory: true)
    }
}
